import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeObject_TriageGen0Test {

    private KeyedObjects2D dataset;
    private final Comparable rowKey1 = "Row1";
    private final Comparable rowKey2 = "Row2";
    private final Comparable colKey1 = "Col1";
    private final Comparable colKey2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveObject_DoesNotRemoveRowWhenOtherObjectsExist() {
        // Setup: Row has two objects
        dataset.addObject("Data1", rowKey1, colKey1);
        dataset.addObject("Data2", rowKey1, colKey2);

        // Action: Remove one object
        dataset.removeObject(rowKey1, colKey1);

        // Verify: Row should still exist because colKey2 is not null
        assertEquals("Data2", dataset.getObject(rowKey1, colKey2));
        assertEquals(1, dataset.getRowCount());
        // Ensure the row index still exists in the internal structure via getRowIndex
        // Since we can't access private fields, we use public API to verify presence
        int rowIndex = dataset.getRowIndex(rowKey1);
        assertEquals("Row1", dataset.getRowKey(rowIndex));
    }








}

