import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeObject_TriageGen0Test {

    private KeyedObjects2D dataset;
    private final Comparable rowKey1 = "Row1";
    private final Comparable rowKey2 = "Row2";
    private final Comparable colKey1 = "Col1";
    private final Comparable colKey2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }



    @Test
    public void testRemoveObject_RemovesRowWhenLastObjectIsRemoved() {
        // Setup: Row has exactly one object
        dataset.addObject("Data1", rowKey1, colKey1);
        assertEquals(1, dataset.getRowCount());

        // Action: Remove the only object
        dataset.removeObject(rowKey1, colKey1);

        // Verify: Row should be removed from rows and rowKeys
        assertEquals(0, dataset.getRowCount());
        assertNull(dataset.getObject(rowKey1, colKey1));

        // Verify rowKey is no longer in the rowKeys list
        boolean rowKeyExists = false;
        for (Object key : dataset.getRowKeys()) {
            if (rowKey1.equals(key)) {
                rowKeyExists = true;
                break;
            }
        }
        assertEquals("RowKey should have been removed", false, rowKeyExists);
    }






}

